/**
 * Expose Element Plus global component types to vue-tsc on a clean checkout.
 *
 * `components.d.ts` is generated by unplugin-vue-components during `vite build`
 * and is git-ignored, so CI type-checks before any build. Without this
 * reference, `el-*` tags resolve to an untyped component and the
 * `@vue-generic` annotations used for typed table row slots fail with TS2558.
 */
/// <reference types="element-plus/global" />
